// One item per Drive folder, tagged with the knowledge source it feeds.
const s = $input.first().json;
const folders = [
  { source: 'guide', folder_id: s.guides_folder_id },
  { source: 'ghl_help', folder_id: s.ghl_help_folder_id },
];
for (const f of folders) {
  if (!f.folder_id || !String(f.folder_id).trim()) {
    throw new Error(`Settings: no folder ID for ${f.source}. Nothing was changed.`);
  }
}
return folders.map((f) => ({ json: f }));

// Safety rule: a listing that is empty, incomplete or missing stops the run before anything is deleted.
// Drive answers a wrong or unshared folder ID with an empty list, not an error.
const folders = $('One item per folder').all();
const listings = $input.all();
if (listings.length !== folders.length) {
  throw new Error(`Expected ${folders.length} Drive listings, got ${listings.length}. Nothing was changed.`);
}
const docs = [];
listings.forEach((item, i) => {
  const { source, folder_id } = $('One item per folder').itemMatching(i).json;
  const { files, nextPageToken } = item.json;
  if (!Array.isArray(files) || files.length === 0) {
    throw new Error(`Drive listing for ${source} (folder ${folder_id}) came back empty. Wrong folder ID, or not shared with the service account? Nothing was changed.`);
  }
  if (nextPageToken) {
    throw new Error(`Drive listing for ${source} has more than 1000 Docs and is incomplete. Nothing was changed.`);
  }
  for (const f of files) {
    docs.push({ json: { doc_id: f.id, title: f.name, modified_time: f.modifiedTime, doc_url: f.webViewLink, source } });
  }
});
return docs;

// Turn each exported Doc into passages: one per "##" section, long sections cut at paragraphs.
// Doc details (title, source, link) come from the Route node; the text from the export.
const MAX_WORDS = 500;

const words = (s) => s.split(/\s+/).filter(Boolean).length;

// Google's Markdown export escapes characters like : [ ] + = . with a backslash. Undo that.
const unescape = (s) => s.replace(/\\([\\`*_{}\[\]()#+\-.!=:<>|~])/g, '$1');

// Cut a long section into balanced parts at blank lines (or at line breaks inside one huge block).
function cut(body) {
  const total = words(body);
  if (total <= MAX_WORDS) return [body];
  let blocks = body.split(/\n{2,}/);
  blocks = blocks.flatMap((b) => (words(b) > MAX_WORDS ? b.split('\n') : [b]));
  const target = total / Math.ceil(total / MAX_WORDS);
  const parts = [];
  let current = [];
  let count = 0;
  for (const block of blocks) {
    const n = words(block);
    if (count > 0 && count + n > target * 1.15) {
      parts.push(current.join('\n\n'));
      current = [];
      count = 0;
    }
    current.push(block);
    count += n;
  }
  if (current.length) parts.push(current.join('\n\n'));
  return parts;
}

const out = [];
for (const [i, item] of $input.all().entries()) {
  const doc = $('Route').itemMatching(i).json;
  const md = unescape(String(item.json.markdown ?? ''))
    .replace(/\r\n?/g, '\n')
    .replace(/[ \t]+$/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  if (!md) throw new Error(`"${doc.title}" exported empty. Nothing was changed for it.`);

  let lines = md.split('\n');

  // GHL help summaries start with "Source: <link to the HighLevel article>". Guides link to themselves.
  let url = doc.doc_url.split('?')[0];
  if (doc.source === 'ghl_help') {
    const m = /^Source:\s*(.+)$/.exec(lines[0]);
    const link = m && (/\((https:\/\/[^)\s]+)\)/.exec(m[1]) || /<(https:\/\/[^>\s]+)>/.exec(m[1]) || /(https:\/\/\S+)/.exec(m[1]));
    if (!link) throw new Error(`"${doc.title}" has no "Source: https://..." first line. Nothing was changed for it.`);
    url = link[1];
    lines = lines.slice(1);
  }

  // Drop the "# Title" line: the title is stored separately and added to every passage below.
  lines = lines.filter((l) => !/^# /.test(l));

  // Split at "## " headings. Text before the first heading (the intro) joins the first section.
  const sections = [];
  const intro = [];
  let current = null;
  for (const line of lines) {
    const h = /^## (.+)$/.exec(line);
    if (h) {
      current = { heading: h[1].trim(), body: [] };
      sections.push(current);
    } else if (current) {
      current.body.push(line);
    } else {
      intro.push(line);
    }
  }
  if (!sections.length) sections.push({ heading: doc.title, body: [] });
  sections[0].body = [...intro, '', ...sections[0].body];

  const passages = [];
  for (const s of sections) {
    const body = s.body.join('\n').replace(/\n{3,}/g, '\n\n').trim();
    if (!body) continue;
    const parts = cut(body);
    parts.forEach((part, n) => {
      const heading = parts.length > 1 ? `${s.heading} (part ${n + 1} of ${parts.length})` : s.heading;
      // Title and heading go into the text too, so both word search and meaning search can match them.
      passages.push({ heading, content: `${doc.title} > ${heading}\n\n${part}` });
    });
  }
  if (!passages.length) throw new Error(`"${doc.title}" has no text to store. Nothing was changed for it.`);

  out.push({
    json: {
      doc_id: doc.doc_id,
      title: doc.title,
      url,
      source: doc.source,
      modified_time: doc.modified_time,
      content_hash: item.json.content_hash,
      passages,
    },
  });
}
return out;

// Pair each passage with its embedding, and check OpenAI returned one of the right size per passage.
const DIMENSIONS = 1536; // must match the database column: embedding vector(1536)

return $input.all().map((item, i) => {
  const doc = $('Split into passages').itemMatching(i).json;
  const data = [...(item.json.data ?? [])].sort((a, b) => a.index - b.index);
  if (data.length !== doc.passages.length) {
    throw new Error(`"${doc.title}": ${doc.passages.length} passages but ${data.length} embeddings. Nothing was changed for it.`);
  }
  const rows = doc.passages.map((p, n) => {
    const embedding = data[n].embedding;
    if (!Array.isArray(embedding) || embedding.length !== DIMENSIONS) {
      throw new Error(`"${doc.title}": embedding ${n + 1} has the wrong size. Nothing was changed for it.`);
    }
    return { content: p.content, heading: p.heading, embedding: JSON.stringify(embedding) };
  });
  return {
    json: {
      doc_id: doc.doc_id,
      title: doc.title,
      url: doc.url,
      source: doc.source,
      content_hash: doc.content_hash,
      modified_time: doc.modified_time,
      rows: JSON.stringify(rows),
    },
  };
});
